import sys
from math import gcd
from functools import reduce

def find_sequence(s):
    if len(s) == 1:
        return [s[0]]

    min_gcd = s[0]
    max_gcd = s[-1]

    def check_sequence(seq):
        unique_gcds = set()
        for i in range(len(seq)):
            for j in range(i, len(seq)):
                current_gcd = reduce(gcd, seq[i:j+1])
                unique_gcds.add(current_gcd)
        return unique_gcds == set(s)

    for n in range(1, 4001):
        seq = [max_gcd] * n
        if check_sequence(seq):
            return seq

        for i in range(n):
            seq[i] = min_gcd
            if check_sequence(seq):
                return seq
            seq[i] = max_gcd

    return [-1]

def main():
    import sys
    input = sys.stdin.read().split()
    m = int(input[0])
    s = list(map(int, input[1:]))

    result = find_sequence(s)
    if result == [-1]:
        print(-1)
    else:
        print(len(result))
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
